import sys,runpy,json,gzip,hashlib,os
from pathlib import Path
args=sys.argv[1:];script=Path(args[0]);out=Path(args[args.index('--result_path')+1]).parent
trace_path=out/'model_inputs.jsonl.gz';temp=out/'.model_inputs-attempt.jsonl.gz'
raw_file=temp.open('xb');compressed=gzip.GzipFile(filename='',mode='wb',fileobj=raw_file,mtime=0)
last_raw=None;pending=None;count=0;source_paths=set();metadata=None

def tensor(value):
    return value.detach().cpu().clone().tolist()
def indices(value,count):
    return list(range(count))[value] if isinstance(value,slice) else list(value)
def profile(frame,event,arg):
    global last_raw,pending,count,metadata
    name=frame.f_code.co_name;filename=frame.f_code.co_filename
    if event=='return' and name=='joint_pos_rel_without_wheel' and filename.endswith('/observations.py') and arg is not None:
        parent=frame.f_back
        if parent is None or parent.f_locals.get('group_name')!='policy':return
        loc=frame.f_locals;asset=loc['asset'];cfg=loc['asset_cfg'];wheel=loc['wheel_asset_cfg'];natural=list(asset.joint_names)
        ids=indices(cfg.joint_ids,len(natural));wids=indices(wheel.joint_ids,len(natural));env=loc['env']
        last_raw={'source_file':filename,'group':'policy','episode_step':int(env.episode_length_buf[0].item()),'native_joint_names':natural,'policy_joint_ids':ids,'policy_joint_names':[natural[i] for i in ids],'wheel_native_ids':wids,'wheel_names':[natural[i] for i in wids],'q_native':tensor(asset.data.joint_pos[0]),'default_q_native':tensor(asset.data.default_joint_pos[0]),'function_output_before_noise':tensor(arg[0])}
        source_paths.add(filename)
    elif name=='act_inference' and filename.endswith('/actor_critic_roa.py'):
        if event=='call':
            parent=frame.f_back
            while parent is not None and parent.f_code.co_name!='_evaluate':parent=parent.f_back
            if parent is None:return
            obs=frame.f_locals['obs']['policy'];env=parent.f_locals['env'].unwrapped;robot=env.scene['robot']
            pending={'step':int(parent.f_locals['step']),'episode_step':int(env.episode_length_buf[0].item()),'phase':'before_native_inference','policy_observation_shape':list(obs.shape),'model_input_flat':tensor(obs.flatten(1)[0]),'raw_observation_function':last_raw,'q_native_at_inference':tensor(robot.data.joint_pos[0]),'default_q_native_at_inference':tensor(robot.data.default_joint_pos[0]),'root_quaternion_wxyz_at_inference':tensor(robot.data.root_quat_w[0]),'command':tensor(env.command_manager.get_command('base_velocity')[0]),'processed_policy_obs_calls':[]}
            source_paths.add(filename)
            if metadata is None:
                manager=env.observation_manager;names=manager._group_obs_term_names['policy'];cfgs=manager._group_obs_term_cfgs['policy'];jcfg=cfgs[names.index('joint_pos')]
                metadata={'version':1,'capture_method':'sys.setprofile call/return observer; no source, arguments, function outputs or tensors modified','timing':'input copied at actual ActorCriticROA.act_inference entry; output copied on return','step_dt':float(env.step_dt),'observation_terms':names,'joint_position_noise':{'enabled':bool(env.cfg.observations.policy.enable_corruption),'operation':jcfg.noise.operation,'n_min':float(jcfg.noise.n_min),'n_max':float(jcfg.noise.n_max)},'normalizer_type':type(frame.f_locals['self'].actor_obs_normalizer).__name__}
        elif event=='return' and pending is not None:
            pending['native_action']=tensor(arg[0]);compressed.write((json.dumps(pending,separators=(',',':'),allow_nan=False)+'\n').encode());count+=1;pending=None
    elif event=='return' and name=='_process_policy_obs' and filename.endswith('/actor_critic_roa.py') and pending is not None and arg is not None:
        pending['processed_policy_obs_calls'].append({'current_frame':tensor(arg[0][0]),'flat_history':tensor(arg[1][0])})

sys.path.insert(0,str(script.parent));sys.argv=args
success=False
try:
    sys.setprofile(profile)
    runpy.run_path(str(script),run_name='__main__')
    success=True
finally:
    sys.setprofile(None);compressed.close();raw_file.close()
    if success and count==500:
        os.link(temp,trace_path);temp.unlink()
        metadata['samples']=count;metadata['trace_sha256']=hashlib.sha256(trace_path.read_bytes()).hexdigest();metadata['runtime_sources']=[{'path':p,'sha256':hashlib.sha256(Path(p).read_bytes()).hexdigest()} for p in sorted(source_paths)]
        with (out/'model_input_trace_metadata.json').open('x') as stream:json.dump(metadata,stream,indent=2)
    else:
        raise RuntimeError(f'incomplete trace: success={success}, samples={count}')
